import argparse
import csv
import json
from decimal import Decimal

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    path = args.get("path", "/inputs/ledger.csv")

    total = Decimal("0.00")
    with open(path, "r", encoding="utf-8", newline="") as f:
        lines = [line for line in f if line.strip()]

    if lines:
        reader = csv.DictReader(lines)
        if reader.fieldnames:
            # Find the 'amount' column case-insensitively and strip whitespace
            amt_col = None
            for col in reader.fieldnames:
                if col and col.strip().lower() == "amount":
                    amt_col = col
                    break
            if amt_col is None:
                amt_col = "amount"

            for row in reader:
                if not row:
                    continue
                raw_val = row.get(amt_col)
                if raw_val is None:
                    continue
                val = raw_val.strip()
                if not val:
                    continue
                # Handle accounting negative format like (100.00) or ($100.00)
                is_neg = False
                if val.startswith("(") and val.endswith(")"):
                    is_neg = True
                    val = val[1:-1].strip()
                if "-" in val:
                    is_neg = True
                    val = val.replace("-", "")
                val = val.replace("$", "").replace(",", "").replace("+", "").strip()
                if val:
                    d = Decimal(val)
                    if is_neg:
                        d = -d
                    total += d

    print(f"{total:.2f}")

if __name__ == "__main__":
    main()
